begin;
set local search_path=public,extensions;
select plan(55);

select ok((select count(*)=5 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['franchise_daily_digest_policy_versions','franchise_daily_digest_config_versions','franchise_daily_digests','franchise_daily_digest_jobs','franchise_daily_digest_job_attempts'])),'five franchise digest records exist');
select ok((select count(*)=5 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['franchise_daily_digest_policy_versions','franchise_daily_digest_config_versions','franchise_daily_digests','franchise_daily_digest_jobs','franchise_daily_digest_job_attempts'])),'RLS is enabled on every digest table');
select ok((select count(*)=5 from pg_policies where schemaname='public'and tablename=any(array['franchise_daily_digest_policy_versions','franchise_daily_digest_config_versions','franchise_daily_digests','franchise_daily_digest_jobs','franchise_daily_digest_job_attempts'])),'each digest table has an explicit read policy');
select ok((select count(*)=4 from pg_trigger where tgname=any(array['franchise_digest_policies_immutable','franchise_digest_configs_immutable','franchise_digests_immutable','franchise_digest_attempts_immutable'])and not tgisinternal),'policies, configs, generated content and attempts are immutable');
select ok(exists(select 1 from pg_trigger where tgname='franchise_digest_snapshot_guard'and not tgisinternal),'generated digest snapshots are schema guarded');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name like'franchise_daily_digest%'and data_type in('real','double precision')),'digest data uses no floating point');
select ok(exists(select 1 from pg_constraint where conrelid='public.franchise_daily_digest_config_versions'::regclass and contype='u'and pg_get_constraintdef(oid)like'%franchise_id, recipient_user_id, version%'),'recipient configuration is append-versioned per franchise');
select ok(exists(select 1 from pg_constraint where conrelid='public.franchise_daily_digests'::regclass and contype='u'and pg_get_constraintdef(oid)like'%franchise_id, digest_date, locale%'),'generation is idempotent per franchise, local date and locale');
select ok(exists(select 1 from pg_constraint where conrelid='public.franchise_daily_digest_jobs'::regclass and contype='u'and pg_get_constraintdef(oid)like'%digest_id, recipient_user_id%'),'one delivery job exists per digest recipient');
select ok(exists(select 1 from pg_constraint where conrelid='public.franchise_daily_digest_job_attempts'::regclass and contype='u'and pg_get_constraintdef(oid)like'%job_id, idempotency_key%'),'worker attempt replay is deduplicated');
select ok((select indexdef like'%WHERE (status = ''ACTIVE''%'from pg_indexes where schemaname='public'and indexname='franchise_digest_one_active_policy_uidx'),'only one digest policy version is active');
select ok((select count(*)=2 from public.notification_template_versions where template_code='FRANCHISE_DAILY_DIGEST'and event_type='FranchiseDailyDigestReadyV1'and status='ACTIVE'and locale in('fr-MA','ar-MA')),'FR and AR notification templates are active');
select ok((select bool_and(variable_keys=array['digest_date','total_prospects','overdue_followups','open_alerts','critical_alerts','global_score_basis_points','active_objectives']::text[])from public.notification_template_versions where template_code='FRANCHISE_DAILY_DIGEST'),'templates expose only bounded aggregate variables');
select ok((select bool_and(body_template~*case when locale='fr-MA'then'aucune sanction automatique'else'عقوبة تلقائية'end)from public.notification_template_versions where template_code='FRANCHISE_DAILY_DIGEST'),'both templates state that the digest never sanctions automatically');
select ok((select prosecdef and proconfig::text like'%search_path=%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='configure_franchise_daily_digest'),'configuration command is hardened');
select ok((select prosrc like'%franchise_crm_write_access%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='configure_franchise_daily_digest'),'only franchise operators may configure recipients');
select ok((select prosrc like'%organization_memberships%'and prosrc like'%FRANCHISE_OWNER%'and prosrc like'%FRANCHISE_MANAGER%'and prosrc like'%FRANCHISE_VIEWER%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='configure_franchise_daily_digest'),'recipient must be an active franchise member');
select ok((select prosrc like'%pg_timezone_names%'and prosrc like'%fr-MA%'and prosrc like'%ar-MA%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='configure_franchise_daily_digest'),'timezone and bilingual locale are validated server-side');
select ok((select prosrc like'%begin_contract_command%'and prosrc like'%finish_contract_command%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='configure_franchise_daily_digest'),'configuration mutation is canonically idempotent');
select ok((select prosrc like'%franchise.daily_digest.configured%'and prosrc like'%FranchiseDailyDigestConfiguredV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='configure_franchise_daily_digest'),'configuration writes audit and Outbox evidence');
select ok((select prosrc like'%pg_advisory_xact_lock%'and prosrc like'%coalesce(prior.version,0)+1%'and prosrc like'%supersedes_config_id%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='configure_franchise_daily_digest'),'configuration history is serialized and linked');
select ok((select prosrc like'%auth.role()<>''service_role''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_franchise_daily_digests'),'only the trusted scheduler may generate digests');
select ok((select prosrc like'%timezone(c.time_zone,p_now)%'and prosrc like'%WEEKDAYS%'and prosrc like'%local_send_time%'and prosrc like'%f.status=''ACTIVE''%'and prosrc like'%franchise_digest_role_access(v.franchise_id,false,v.recipient_user_id)%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_franchise_daily_digests'),'scheduler honors local time and frequency while skipping recipients outside the exact active franchise scope');
select ok((select prosrc like'%franchise_crm_prospects%'and prosrc like'%franchise_performance_score_snapshots%'and prosrc like'%franchise_performance_alerts%'and prosrc like'%franchise_performance_objective_versions%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_franchise_daily_digests'),'digest composes CRM, performance, alerts and objectives');
select ok((select prosrc not like'%display_name%'and prosrc not like'%contact_email%'and prosrc not like'%summary%'and prosrc not like'%evidence_refs%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_franchise_daily_digests'),'digest composition never selects CRM PII or evidence text');
select ok((select prosrc like'%max_pipeline_stages%'and prosrc like'%limit(select%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_franchise_daily_digests'),'pipeline aggregation is bounded by the policy version');
select ok((select prosrc like'%on conflict(franchise_id,digest_date,locale)do nothing%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_franchise_daily_digests'),'digest generation safely deduplicates scheduler replay');
select ok((select prosrc like'%on conflict(digest_id,recipient_user_id)do nothing%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_franchise_daily_digests'),'recipient job generation safely deduplicates replay');
select ok((select prosrc like'%franchise.daily_digest.scheduled%'and prosrc like'%FranchiseDailyDigestScheduledV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_franchise_daily_digests'),'scheduling writes audit and Outbox evidence');
select ok((select prosrc like'%auth.role()<>''service_role''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='claim_franchise_daily_digest_jobs'),'only the trusted worker may claim jobs');
select ok((select prosrc like'%for update of x skip locked%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='claim_franchise_daily_digest_jobs'),'concurrent workers use skip-locked claims');
select ok((select prosrc like'%leased_until<=clock_timestamp()%'and prosrc like'%attempt_count=attempt_count+1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='claim_franchise_daily_digest_jobs'),'expired leases are reclaimable and counted');
select ok((select prosrc like'%franchise.daily_digest.claimed%'and prosrc like'%FranchiseDailyDigestClaimedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='claim_franchise_daily_digest_jobs'),'claims write audit and Outbox evidence');
select ok((select prosrc like'%auth.role()<>''service_role''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_franchise_daily_digest_job'),'only the trusted worker may complete jobs');
select ok((select prosrc like'%INVALID_FRANCHISE_DIGEST_LEASE%'and prosrc like'%STALE_FRANCHISE_DIGEST_JOB%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_franchise_daily_digest_job'),'completion validates lease ownership, expiry and row version');
select ok((select prosrc like'%enqueue_notification%'and prosrc like'%FRANCHISE_DAILY_DIGEST%'and prosrc like'%FranchiseDailyDigestReadyV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_franchise_daily_digest_job'),'completion delegates delivery to versioned notification templates');
select ok((select prosrc like'%franchise_daily_digest_job_attempts%'and prosrc like'%franchise.daily_digest.notified%'and prosrc like'%FranchiseDailyDigestNotifiedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_franchise_daily_digest_job'),'completion preserves delivery proof, audit and Outbox history');
select ok((select prosrc like'%auth.role()<>''service_role''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='fail_franchise_daily_digest_job'),'only the trusted worker may fail jobs');
select ok((select prosrc like'%base_backoff_seconds*power(2%'and prosrc like'%max_backoff_seconds%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='fail_franchise_daily_digest_job'),'retry uses bounded exponential backoff from the frozen policy');
select ok((select prosrc like'%attempt_count>=pol.max_attempts%'and prosrc like'%DEAD_LETTER%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='fail_franchise_daily_digest_job'),'retry exhaustion dead-letters the job');
select ok((select prosrc like'%franchise.daily_digest.dead_lettered%'and prosrc like'%FranchiseDailyDigestFailedV1%'and prosrc like'%FranchiseDailyDigestDeadLetteredV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='fail_franchise_daily_digest_job'),'failure outcomes write audit and Outbox evidence');
select ok((select count(*)=5 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['configure_franchise_daily_digest','schedule_franchise_daily_digests','claim_franchise_daily_digest_jobs','complete_franchise_daily_digest_job','fail_franchise_daily_digest_job'])),'all five public commands are hardened security-definer functions');
select ok(has_function_privilege('authenticated','public.configure_franchise_daily_digest(uuid,uuid,boolean,text,time without time zone,text,text,text,text,uuid)','EXECUTE')and not has_function_privilege('service_role','public.configure_franchise_daily_digest(uuid,uuid,boolean,text,time without time zone,text,text,text,text,uuid)','EXECUTE'),'only authenticated franchise operators receive configuration execution');
select ok((select count(*)=4 and bool_and(has_function_privilege('service_role',p.oid,'EXECUTE')and not has_function_privilege('authenticated',p.oid,'EXECUTE')and not has_function_privilege('anon',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['schedule_franchise_daily_digests','claim_franchise_daily_digest_jobs','complete_franchise_daily_digest_job','fail_franchise_daily_digest_job'])),'worker RPCs are service-role only');
select ok(not has_table_privilege('authenticated','public.franchise_daily_digest_config_versions','INSERT')and not has_table_privilege('service_role','public.franchise_daily_digest_jobs','UPDATE')and not has_table_privilege('service_role','public.franchise_daily_digest_job_attempts','INSERT'),'no role bypasses narrow command APIs with direct writes');
select ok(not has_table_privilege('anon','public.franchise_daily_digests','SELECT')and not has_table_privilege('anon','public.franchise_daily_digest_jobs','SELECT'),'anonymous digest access is denied');
select ok((select count(*)=4 and bool_and(qual like'%franchise_digest_role_access%'and qual not like'%franchise_access(%')from pg_policies where schemaname='public'and tablename=any(array['franchise_daily_digest_config_versions','franchise_daily_digests','franchise_daily_digest_jobs','franchise_daily_digest_job_attempts'])),'all franchise digest records require the dedicated active-role helper and reject the broad organization helper');
select ok((select prosrc not like'%update public.franchises%'and prosrc not like'%insert into public.franchise_performance_alerts%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_franchise_daily_digests'),'scheduler performs no autonomous sanction or alert decision');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name in('franchise_daily_digests','franchise_daily_digest_jobs','franchise_daily_digest_job_attempts')and column_name~*'(name|email|phone|address|contact|password)'),'digest delivery history stores no direct contact PII');
select ok(exists(select 1 from pg_indexes where schemaname='public'and indexname='franchise_digest_job_dispatch_idx'and indexdef like'%QUEUED%'and indexdef like'%CLAIMED%'),'pending and expired jobs have a bounded dispatch index');
select ok(exists(select 1 from information_schema.columns where table_schema='public'and table_name='franchise_daily_digest_jobs'and column_name='notification_id'),'job history links the notification delivery proof');
select ok((select data_type='integer'from information_schema.columns where table_schema='public'and table_name='franchise_daily_digest_policy_versions'and column_name='max_attempts'),'retry quantities use exact integers');
select ok((select count(*)=2 and bool_and(cta_path_template in('/fr/franchise/gouvernance','/ar/franchise/gouvernance'))from public.notification_template_versions where template_code='FRANCHISE_DAILY_DIGEST'),'localized templates route to the matching FR or AR franchise workspace');
select ok((select prosrc like'%p_limit not between 1 and 500%'and prosrc like'%order by v.franchise_id,v.recipient_user_id%limit p_limit%'and strpos(prosrc,'limit p_limit')<strpos(prosrc,'local_date:=')and prosrc not like'%p_limit:=p_limit-1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='schedule_franchise_daily_digests'),'scheduler validates p_limit and bounds deterministic candidate iterations before composition work');
select ok((select prosrc not like'%metrics_snapshot''%'and prosrc not like'%recipient_user_id''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='claim_franchise_daily_digest_jobs'),'worker claim result exposes only job and lease identifiers');

select * from finish();
rollback;
